/*
 * A182654  Floor-sum sequence of r, with r=sqrt(2) and a(1)=1, a(2)=2.
 * https://oeis.org/A182654
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is generated by the closure of the floor‑sum rule * with r
 *            = sqrt(2) starting from the two Seed elements 1 and 2
 * Range:     u8 n <= 2, u16 n <= 30, u32 n <= 69, u64 n <= 69, u128 n <= 69,
 *            big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The algorithm maintains the set S of already generated terms
 * in strictly increasing order.  A min‑heap stores all
 * values floor((m+n)*sqrt(2)) that can currently be produced
 * from an existing pair (m,n) with m<n.  While generating new
 * terms, each new element produces candidates with all
 * earlier S elements, and these are inserted into the heap.
 * Duplicate candidates are discarded before adding a new
 * term to S.  The sequence is memoised in a static array, so
 * successive calls to a(n) are fast and unordered. */

#include <stdlib.h>
#include <stdbool.h>
#include <stddef.h>

#include "../utils/floor_sqrt.h"

/* ------------------------------------------------------------------ */
/*  Heap utilities                                                      */
/* ------------------------------------------------------------------ */
static seq_t *heap = NULL;
static size_t heap_cap = 0;
static size_t heap_len = 0;

static void heap_push(seq_t val)
{
    if (heap_len == heap_cap) {
        heap_cap = heap_cap ? heap_cap * 2 : 4;
        heap = (seq_t *)realloc(heap, heap_cap * sizeof(seq_t));
    }
    size_t i = heap_len++;
    heap[i] = val;
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (heap[p] <= heap[i])
            break;
        seq_t t = heap[p];
        heap[p] = heap[i];
        heap[i] = t;
        i = p;
    }
}

static seq_t heap_pop(void)
{
    seq_t minv = heap[0];
    heap[0] = heap[--heap_len];
    size_t i = 0;
    while (1) {
        size_t l = (i << 1) + 1;
        if (l >= heap_len)
            break;
        size_t r = l + 1;
        size_t child = (r < heap_len && heap[r] < heap[l]) ? r : l;
        if (heap[i] <= heap[child])
            break;
        seq_t t = heap[i];
        heap[i] = heap[child];
        heap[child] = t;
        i = child;
    }
    return minv;
}

/* ------------------------------------------------------------------ */
/*  Binary search in the ascending array S (size = len)               */
/* ------------------------------------------------------------------ */
static bool contains(const seq_t *arr, idx_t len, seq_t val)
{
    idx_t lo = 0, hi = len;
    while (lo < hi) {
        idx_t mid = (lo + hi) >> 1;
        if (arr[mid] == val)
            return true;
        if (arr[mid] < val)
            lo = mid + 1;
        else
            hi = mid;
    }
    return false;
}

/* ------------------------------------------------------------------ */
/*  Main sequence function                                            */
/* ------------------------------------------------------------------ */
seq_t a(idx_t n)
{
    static seq_t *S = NULL;          /* array of sequence terms */
    static size_t S_cap = 0;         /* current capacity          */
    static idx_t S_len = 0;          /* number of terms stored    */

    if (n == 0)            /* offset is 1, so n>=1 expected */
        return (seq_t)0;

    /* Grow the sequence until length >= n */
    while (S_len < n) {
        if (S_len == 0) {
            /* Initialisation */
            if (S_cap < 2) {
                S_cap = 2;
                S = (seq_t *)realloc(S, S_cap * sizeof(seq_t));
            }
            S[0] = (seq_t)1;
            S[1] = (seq_t)2;
            S_len = 2;

            if (heap_cap < 4) {
                heap_cap = 4;
                heap = (seq_t *)realloc(heap, heap_cap * sizeof(seq_t));
            }
            heap_len = 0;
            /* push the first candidate from 1 and 2 */
            seq_t k = S[0] + S[1];
            seq_t cand = floor_sqrt(((k * k) << 1));
            heap_push(cand);
        } else {
            /* Pop the smallest candidate that is not already in S */
            seq_t cand;
            do {
                cand = heap_pop();
            } while (contains(S, S_len, cand));

            /* Append new term */
            if (S_len == S_cap) {
                S_cap = S_cap ? S_cap * 2 : 2;
                S = (seq_t *)realloc(S, S_cap * sizeof(seq_t));
            }
            S[S_len] = cand;
            S_len++;

            /* Generate new candidates involving the new element */
            for (idx_t i = 0; i < S_len - 1; ++i) {
                seq_t sum = S[S_len - 1] + S[i];
                seq_t new_cand = floor_sqrt(((sum * sum) << 1));
                heap_push(new_cand);
            }
        }
    }

    return S[n - 1];
}
